"""Writes crates/dv-render/src/colormaps.rs: 256-step colormap tables in sRGB.

Usage: gen-colormaps.py <out.rs>

Viridis is by Stéfan van der Walt and Nathaniel Smith, released CC0 with matplotlib.
"""

import sys

from matplotlib import colormaps

names = ["viridis"]
lines = [
    "//! 256-step colormap tables in sRGB, generated by scripts/gen-colormaps.py from matplotlib.",
    "//! Viridis is by Stéfan van der Walt and Nathaniel Smith, released CC0.",
    "",
]
for name in names:
    cm = colormaps[name].resampled(256)
    lines.append(f"pub const {name.upper()}: [[u8; 3]; 256] = [")
    for i in range(256):
        r, g, b, _ = cm(i)
        lines.append(f"    [{round(r * 255)}, {round(g * 255)}, {round(b * 255)}],")
    lines.append("];")
open(sys.argv[1], "w").write("\n".join(lines) + "\n")
